*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);-webkit-font-smoothing:antialiased}header{height:70px;background:#303337;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 4%;gap:16px}.brand{display:flex;align-items:center;gap:13px;font-size:14px;font-weight:750;letter-spacing:.07em}.mark{width:27px;height:27px;background:#51565d;color:#e9ebed;display:grid;place-items:center;font-family:var(--mono);font-size:18px;border-radius:6px}.brand span:last-child{color:var(--muted);font-weight:400;letter-spacing:0}.top-status{display:flex;align-items:center;gap:16px;font-size:11px;color:var(--muted)}.dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:currentColor;margin-right:6px}main{max-width:1480px;margin:auto;padding:36px 4% 24px}h2{font-size:16px;font-weight:650;margin:0}h3{font-size:13px;margin:0;font-weight:650}p{margin:0}.overview{display:grid;grid-template-columns:1fr 1fr;background:var(--paper);border:1px solid var(--line);border-radius:10px;margin-bottom:32px;overflow:hidden}.stat{padding:21px 24px;border-right:1px solid var(--line);min-width:0}.stat:last-child{border:0}.stat-label{font-size:11px;color:var(--muted);display:flex;align-items:center;justify-content:space-between;gap:10px}.stat-value{font-size:34px;font-weight:550;font-variant-numeric:tabular-nums;letter-spacing:-1.4px;margin:10px 0 7px;line-height:1.1}.stat-sub{font-size:11px;color:var(--muted);line-height:1.6;overflow-wrap:anywhere}.accent{color:var(--accent)}.section-title{display:flex;align-items:center;justify-content:space-between;margin:0 0 13px;gap:12px}.section-title>div{display:flex;align-items:center;gap:10px}.section-note{font-size:10px;color:var(--muted)}.count{font:10px var(--mono);background:#3e4349;color:#b5bbc2;border-radius:4px;padding:3px 6px}.workspace{display:grid;grid-template-columns:1fr;gap:26px;align-items:start}.panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;overflow:hidden}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}.mono{font-family:var(--mono);font-size:10px;color:var(--muted);overflow-wrap:anywhere}.badge{display:inline-flex;align-items:center;white-space:nowrap;border-radius:4px;background:#41464c;color:#b7bec5;font-size:10px;padding:4px 7px;line-height:1.2}.badge.running{background:#3c4b43;color:var(--green)}.badge.error{background:#503e3e;color:var(--red)}.note{font-size:11px;line-height:1.8;color:var(--muted);margin-top:10px;overflow-wrap:anywhere;white-space:pre-wrap}details{font-size:11px;color:var(--muted)}summary{cursor:pointer;line-height:1.7;list-style:none}summary::before{content:'＋';margin-right:5px;color:#a1a8af}details[open]>summary::before{content:'−'}summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}details[open]>summary{margin-bottom:9px}dl{display:grid;grid-template-columns:60px minmax(0,1fr);gap:6px;margin:0;line-height:1.7}dt{color:var(--muted)}dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--ink)}.scouts{display:grid;grid-template-columns:1fr 1fr;gap:12px}.scout{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:17px;min-width:0;display:flex;flex-direction:column}.scout-head{display:flex;align-items:center;gap:9px;margin-bottom:15px}.avatar{flex:none;width:28px;height:28px;border:1px solid var(--line);border-radius:7px;display:grid;place-items:center;font:12px var(--mono);font-weight:600;background:#303337}.scout-name{font-size:11px;font-weight:600}.scout-model{font-size:9px;color:var(--muted);margin-top:3px}.scout-body{font-size:12px;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere;flex:1;min-height:67px}.scout-body.empty-text{color:#9ba2ab}.scout-foot{border-top:1px solid var(--line);padding-top:11px;margin-top:16px;display:flex;justify-content:space-between;align-items:center;gap:8px;font:9px var(--mono);color:var(--muted)}.scout-next{font-size:9px;color:var(--muted);margin-top:8px}.scout details{margin-top:9px;color:var(--red);font-size:10px}.error-text{overflow-wrap:anywhere;white-space:pre-wrap;line-height:1.7}.empty{padding:40px 24px;text-align:center;color:var(--muted)}.empty-symbol{margin:0 auto 14px;border:1px dashed #626870;border-radius:9px;width:40px;height:40px;display:grid;place-items:center;font:20px var(--mono);color:#858e99}.empty-title{color:#c0c5cb;font-size:13px;margin-bottom:7px}.empty-desc{font-size:11px;line-height:1.9}.metrics-section{margin-top:30px}.metrics-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.metric-heading{padding:16px 19px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:11px}th{font-size:9px;color:var(--muted);font-weight:400;text-align:right;white-space:nowrap;background:#303337;padding:10px 16px}th:first-child,td:first-child{text-align:left}td{text-align:right;padding:12px 16px;border-top:1px solid #41464c;white-space:nowrap;font-variant-numeric:tabular-nums}.route{max-width:260px;white-space:normal;font-family:var(--mono);font-size:10px;overflow-wrap:anywhere;line-height:1.7}.method{font-size:9px;color:var(--green);margin-right:7px}.node-label{font-size:9px;color:var(--muted);margin-top:3px}.hosts{grid-column:1/-1;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1px;background:var(--line)}.host{background:var(--paper);padding:18px 21px}.host-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.host-head span{font-size:10px;color:var(--muted)}.host-row{display:flex;justify-content:space-between;font-size:10px;margin:9px 0;color:var(--muted)}.host-row strong{font:11px var(--mono);color:var(--ink);font-weight:500}.bar{height:4px;background:#454b52;border-radius:5px;overflow:hidden}.bar-fill{height:100%;background:#91b69d;border-radius:5px}.bar-fill.hot{background:var(--accent)}.evidence{margin-top:14px;padding:14px 18px;background:transparent;border:1px solid var(--line);border-radius:8px}.evidence pre{white-space:pre-wrap;overflow-wrap:anywhere;font:10px/1.7 var(--mono);max-height:340px;overflow:auto;margin:8px 0}.evidence>div{margin-top:10px}.metrics-error{padding:12px 18px;background:#464339;border-radius:6px;font-size:11px;color:#d0c29f;line-height:1.8;margin-bottom:14px}.metrics-error details{margin-top:6px}.empty-metrics{display:flex;justify-content:space-between;align-items:center;padding:28px;gap:24px}.empty-lines{width:160px;flex:none;display:grid;gap:9px}.empty-lines i{height:5px;border-radius:3px;background:#474d54;display:block}.empty-lines i:nth-child(2){width:73%}.empty-lines i:nth-child(3){width:44%}footer{border-top:1px solid var(--line);margin-top:30px;padding-top:16px;display:flex;justify-content:space-between;gap:12px;font:9px var(--mono);color:var(--muted)}#connection-error{background:#503e3e;color:var(--red);padding:12px 16px;border-radius:6px;margin-bottom:18px;font-size:12px;line-height:1.6}#connection-error:empty{display:none}@media(min-width:1500px){header{padding-left:calc((100vw - 1362px)/2);padding-right:calc((100vw - 1362px)/2)}}@media(max-width:1000px){.workspace{grid-template-columns:1fr}.scouts{grid-template-columns:repeat(4,1fr)}.stat{padding:18px}.stat-value{font-size:29px}.scout{padding:14px}}@media(max-width:760px){main{padding:25px 18px}header{padding:0 18px;height:60px}.brand span:last-child{display:none}.top-status{gap:8px}.overview{grid-template-columns:1fr 1fr}.stat:nth-child(2){border-right:0}.stat:nth-child(-n+2){border-bottom:1px solid var(--line)}.scouts,.metrics-grid{grid-template-columns:1fr 1fr}.metrics-grid>.panel:not(.hosts){grid-column:1/-1}.scout-body{min-height:50px}.section-note{font-size:9px}.empty-lines{width:75px}.stat-value{font-size:28px}}@media(prefers-reduced-motion:no-preference){.bar-fill{transition:width .4s ease}}

.score-section{margin-bottom:28px}.score-panel{padding:18px 20px 12px}.score-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:12px}.score-legend{display:flex;gap:15px;flex-wrap:wrap;font-size:10px;color:var(--muted)}.score-legend .pass{color:var(--accent)}.score-legend .fail{color:var(--red)}.score-scroll{overflow-x:auto}.score-svg{width:100%;min-width:530px;height:215px;display:block}.score-grid{stroke:var(--line);stroke-width:1;stroke-dasharray:3 5}.score-axis{fill:var(--muted);font:10px var(--mono)}.score-line{fill:none;stroke:var(--accent);stroke-width:2;stroke-linejoin:round}.score-point{cursor:pointer;outline:none}.score-point circle{stroke:var(--paper);stroke-width:2}.score-point:focus circle,.score-point:hover circle{stroke:var(--ink);stroke-width:3}.score-detail{min-height:30px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:12px;margin-top:4px;color:var(--muted);font:10px/1.7 var(--mono)}.score-detail strong{color:var(--ink);font-size:12px;font-weight:500}.score-empty{padding:22px 0;text-align:center;font-size:11px;line-height:1.8;color:var(--muted)}@media(max-width:760px){.score-panel{padding:15px}.score-heading{align-items:flex-start}.score-legend{gap:8px}.score-detail{gap:7px}}
</style>
</head>
<body>
<header><div class="brand"><div class="mark">i.</div>ISU SCAFFOLD <span>/ Operations</span></div><div class="top-status"><span id="daemon">scout 停止</span><span id="updated">接続中</span></div></header>
<main>

<div id="connection-error" role="status"></div>
<div class="overview" id="overview"></div>
<section class="score-section"><div class="panel score-panel" id="score-history"></div></section>
<div class="workspace">
<section><div class="section-title"><div><h2>Scout</h2><span class="count">04</span></div><span class="section-note">各scoutの最新報告</span></div><div id="scouts" class="scouts"></div></section>
</div>
<section class="metrics-section"><div class="section-title"><div><h2>計測</h2><span class="count">ISUSCOPE</span></div><span class="section-note" id="metric-time">計測結果を待っています</span></div><div id="metrics"></div></section>
<footer><span>ISU SCAFFOLD / OPERATIONS BOARD</span><span>状態 5秒更新 · 計測 30秒更新</span></footer>
</main>
<script>
const labels={running:'探索中',waiting:'待機',stopped:'停止',error:'エラー'};
const names={claude:['Claude Code','Anthropic','C'],codex:['Codex','OpenAI','O'],kimi:['Kimi Code','Kimi K3','K'],opencode:['OpenCode','DeepSeek · Zen','D']};
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e};
const num=(n,d=0)=>n==null?'—':Number(n).toLocaleString('ja-JP',{maximumFractionDigits:d});
const short=s=>s?s.slice(0,8):'—';
const time=t=>t?new Date(t*1000).toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'}):'未投稿';
const date=t=>t?new Date(t*1000).toLocaleString('ja-JP'):'—';
function badge(state){return el('span',labels[state]||state,'badge '+state)}
function empty(parent,title,desc){const box=el('div',null,'empty');box.append(el('div','·','empty-symbol'),el('p',title,'empty-title'),el('p',desc,'empty-desc'));parent.append(box)}
function disclosure(parent,title,key){const d=el('details');if(key)d.dataset.key=key;d.append(el('summary',title));parent.append(d);return d}
function dataList(parent,pairs){const dl=el('dl');for(const [key,value]of pairs)dl.append(el('dt',key),el('dd',value||'—'));parent.append(dl)}
function stat(label,value,sub,cls=''){const s=el('div',null,'stat');s.append(el('p',label,'stat-label'),el('div',value,'stat-value '+cls),el('p',sub,'stat-sub'));return s}
function renderOverview(d){const q=d.metrics||{},run=q.latest,base=q.base;const score=run?.score;let delta='比較元が未指定';if(base&&score!=null&&base.score!=null){const diff=score-base.score;delta=`${diff>=0?'+':''}${num(diff)} vs ${base.short_id||short(base.id)}`;}const root=document.querySelector('#overview');root.replaceChildren(stat('最新スコア',num(score),run?`${run.passed===true?'PASS · ':run.passed===false?'FAIL · ':''}${delta}`:'最初の計測結果を待っています',score!=null?'accent':''),stat('Scoutの報告',`${(d.scouts||[]).filter(s=>s.report!=null).length} / 4`,d.daemon_running?'投稿完了から15分後に再探索':'定期探索は停止中'));}
let selectedRun=null;
const svgEl=(tag,attrs={},text)=>{const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!=null)e.textContent=text;return e};
function renderScoreHistory(q){
 const root=document.querySelector('#score-history');root.replaceChildren();
 const head=el('div',null,'score-heading'),title=el('div'),legend=el('div',null,'score-legend');title.append(el('h3','スコアの推移'));legend.append(el('span','● PASS','pass'),el('span','× FAIL / 中断','fail'),el('span','○ 判定なし'));head.append(title,legend);root.append(head);
 const runs=(q.score_history||[]).map(r=>({...r,t:Date.parse(r.started_at)})).filter(r=>Number.isFinite(r.t)).sort((a,b)=>a.t-b.t);
 if(!runs.length){root.append(el('p','完了したrunが記録されると、ここにスコアの推移が表示されます。','score-empty'));return}
 const note=el('p',`直近100件のrunから終了分 ${runs.length}件 · 横軸はrun開始時刻`,'section-note');note.style.marginBottom='10px';root.append(note);
 const scroll=el('div',null,'score-scroll'),svg=svgEl('svg',{viewBox:'0 0 1100 215',class:'score-svg',role:'group','aria-label':'run開始時刻に対するスコアの推移。各点にフォーカスすると詳細を表示します。'});scroll.append(svg);root.append(scroll);
 const detail=el('div',null,'score-detail');root.append(detail);
 const hasScore=r=>typeof r.score==='number'&&Number.isFinite(r.score);
 const failed=r=>r.passed===false||['failed','aborted'].includes(r.state);
 const left=65,right=1080,top=12,bottom=158,missingY=182;
 let t0=runs[0].t,t1=runs[runs.length-1].t;if(t0===t1){t0-=60000;t1+=60000;}
 const scores=runs.filter(hasScore).map(r=>r.score),max=Math.max(1,...scores)*1.12,min=Math.min(0,...scores);
 const x=r=>left+(r.t-t0)/(t1-t0)*(right-left),y=r=>hasScore(r)?bottom-(r.score-min)/(max-min)*(bottom-top):missingY;
 for(let i=0;i<=4;i++){const yy=bottom-i*(bottom-top)/4;svg.append(svgEl('line',{x1:left,x2:right,y1:yy,y2:yy,class:'score-grid'}),svgEl('text',{x:left-12,y:yy+3,'text-anchor':'end',class:'score-axis'},num(min+i*(max-min)/4)));}
 const multiDay=new Date(t0).toDateString()!==new Date(t1).toDateString();
 for(let i=0;i<=4;i++){const t=t0+(t1-t0)*i/4,label=new Date(t).toLocaleString('ja-JP',{...(multiDay?{month:'numeric',day:'numeric'}:{}),hour:'2-digit',minute:'2-digit'});svg.append(svgEl('text',{x:left+i*(right-left)/4,y:208,'text-anchor':i===0?'start':i===4?'end':'middle',class:'score-axis'},label));}
 if(runs.some(r=>!hasScore(r)))svg.append(svgEl('text',{x:left-12,y:missingY+3,'text-anchor':'end',class:'score-axis'},'未取得'));
 let path='';let connected=false;for(const r of runs){if(r.passed===true&&!failed(r)&&hasScore(r)){path+=(connected?' L ':' M ')+x(r)+' '+y(r);connected=true;}else connected=false;}if(path)svg.append(svgEl('path',{d:path,class:'score-line'}));
 function show(r){selectedRun=r.id;const state=failed(r)?(r.state==='aborted'?'中断':'FAIL'):r.passed===true?'PASS':'判定なし';detail.replaceChildren(el('strong',hasScore(r)?num(r.score):'スコア未取得'),el('span',state),el('span',new Date(r.t).toLocaleString('ja-JP')),el('span','run '+(r.short_id||short(r.id))),el('span','commit '+short(r.commit_hash)+(r.dirty?' (dirty)':'')));}
 for(const r of runs){const cx=x(r),cy=y(r),color=failed(r)?'var(--red)':r.passed===true?'var(--accent)':'var(--muted)';const point=svgEl('g',{class:'score-point',tabindex:0,role:'img','aria-label':`${new Date(r.t).toLocaleString('ja-JP')} / ${failed(r)?'FAIL・中断':r.passed===true?'PASS':'判定なし'} / スコア ${hasScore(r)?r.score:'未取得'} / run ${r.short_id||r.id}`});point.append(svgEl('circle',{cx,cy,r:9,fill:'transparent',stroke:'none'}));if(failed(r)){point.append(svgEl('path',{d:`M ${cx-4} ${cy-4} L ${cx+4} ${cy+4} M ${cx+4} ${cy-4} L ${cx-4} ${cy+4}`,stroke:color,'stroke-width':2}));}else point.append(svgEl('circle',{cx,cy,r:4.5,fill:r.passed===true?color:'var(--paper)',style:`stroke:${color}`}));point.append(svgEl('title',{},`${r.short_id||r.id} · ${hasScore(r)?num(r.score):'スコア未取得'}`));for(const event of ['mouseenter','focus','click'])point.addEventListener(event,()=>show(r));svg.append(point);}
 show(runs.find(r=>r.id===selectedRun)||runs[runs.length-1]);
}
function renderScouts(scouts){const root=document.querySelector('#scouts');root.replaceChildren();for(const name of ['claude','codex','kimi','opencode']){const s=scouts.find(x=>x.name===name)||{name,state:'stopped'},n=names[name];const card=el('article',null,'scout'),head=el('div',null,'scout-head'),identity=el('div');identity.append(el('p',n[0],'scout-name'),el('p',n[1],'scout-model'));head.append(el('div',n[2],'avatar'),identity);card.append(head,el('p',s.report??'まだ報告はありません。','scout-body'+(s.report==null?' empty-text':'')));const foot=el('div',null,'scout-foot');const posted=el('time',time(s.posted_at));posted.title=date(s.posted_at);foot.append(badge(s.state),posted);card.append(foot);if(s.next_at&&s.state!=='stopped')card.append(el('p',`次回 ${date(s.next_at)}`,'scout-next'));if(s.error){const detail=disclosure(card,'接続・実行の確認が必要','scout-'+name);detail.append(el('p',s.error,'error-text'));}root.append(card)}}
function table(parent,heads,rows){const scroll=el('div',null,'table-scroll'),t=el('table'),thead=el('thead'),tr=el('tr');heads.forEach(h=>tr.append(el('th',h)));thead.append(tr);t.append(thead);const body=el('tbody');rows.forEach(row=>{const tr=el('tr');row.forEach(value=>{const td=el('td');value instanceof Node?td.append(value):td.textContent=value??'—';tr.append(td)});body.append(tr)});t.append(body);scroll.append(t);parent.append(scroll)}
