"""On-demand, bounded board queries. Never used as scout input."""
from collections import OrderedDict
import re
import threading
import time
from inputs import command_json
from store import git


def selection(params):
    if set(params) - {'run', 'base', 'limit'} or any(len(v) != 1 for v in params.values()):
        raise ValueError('run / base / limitを1つずつ指定してください')
    run = params.get('run', [''])[0]
    base = params.get('base', [''])[0]
    for value in (run, base):
        if value and not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.:-]{0,159}', value):
            raise ValueError('run IDが不正です')
    if not run:
        raise ValueError('表示runを指定してください')
    limit = params.get('limit', ['50'])[0]
    if limit not in ('25', '50', '100'):
        raise ValueError('取得件数は25 / 50 / 100です')
    return run, base, int(limit)


def detail(repo, cfg, run, base='', limit=50):
    def read(args):
        return command_json(repo, cfg['isuscope'] + args, max_bytes=2_000_000)
    brief = read(['brief', run, '--limit', '5'])
    if 'error' in brief:
        return {'error': brief['error']}
    candidate = brief.get('run', {})
    if candidate.get('state') not in ('complete', 'degraded', 'failed', 'aborted'):
        return {'error': '終了したrunを選んでください'}
    result = {'latest': candidate, 'brief': brief, 'base': None, 'sections': {},
              'collected_at': time.time(), 'current_commit': git(repo, 'rev-parse', 'HEAD'),
              'dirty': bool(git(repo, 'status', '--porcelain'))}
    if base:
        baseline = read(['brief', base, '--limit', '1'])
        if 'error' in baseline or baseline.get('run', {}).get('state') not in ('complete', 'degraded', 'failed', 'aborted'):
            return {'error': baseline.get('error', '終了した比較元runを選んでください')}
        result['base'] = baseline['run']
    for name, args in (('http', ['--view', 'http']),
                       ('sql', ['--view', 'database', '--window', 'load'])):
        argv = ['query', candidate['id'], *args, '--limit', str(limit)]
        if result['base']:
            argv += ['--base', result['base']['id']]
        result['sections'][name] = {'command': cfg['isuscope'] + argv, 'data': read(argv)}
    return result


class DetailCache:
    """Serialize expensive CLI reads and keep at most eight selections for 30s."""
    def __init__(self):
        self.lock = threading.Lock()
        self.items = OrderedDict()

    def get(self, repo, cfg, run, base, limit):
        key = (tuple(cfg['isuscope']), run, base, limit)
        with self.lock:
            now = time.monotonic()
            cached = self.items.get(key)
            if cached and now - cached[0] < 30:
                self.items.move_to_end(key)
                return cached[1]
            value = detail(repo, cfg, run, base, limit)
            self.items[key] = (time.monotonic(), value)
            self.items.move_to_end(key)
            while len(self.items) > 8:
                self.items.popitem(last=False)
            return value
#[derive(Default)]
struct BucketRow {
    cpu_host_sampler: Vec<f64>,
    cpu_sysstat: Vec<f64>,
    cpu_other: Vec<f64>,
    memory: Vec<f64>,
    load: Vec<f64>,
    disk_util: Vec<f64>,
    disk_await: Vec<f64>,
    http_requests: f64,
    http_p95: Vec<f64>,
    http_errors: f64,
    /// SQL別の5秒bucket（slp以前の自前解析）の合計。
    db_calls: f64,
    db_time: f64,
    /// DB全体の5秒bucket（slp collectorの`db.calls`・`db.duration`）。あればこちらを使う。
    db_total_calls: Option<f64>,
    db_total_time: Option<f64>,
}

impl BucketRow {
    /// DB全体の値があればそれを、無ければSQL別の値の合計を返す。両方を足すと二重に数える。
    fn database(&self) -> (Option<f64>, Option<f64>) {
        if self.db_total_calls.is_some() || self.db_total_time.is_some() {
            return (
                Some(self.db_total_calls.unwrap_or_default()),
                Some(self.db_total_time.unwrap_or_default()),
            );
        }
        (
            observed_sum(self.db_calls, self.db_time != 0.0),
            observed_sum(self.db_time, self.db_calls != 0.0),
        )
    }
}

#[derive(Debug)]
struct SeriesOptions {
    metrics: Vec<String>,
    node: Option<String>,
    labels: Vec<(String, String)>,
    from: u64,
    to: Option<u64>,
    window: SeriesWindowArg,
    bucket: u64,
    limit: usize,
}

#[derive(serde::Serialize)]
struct SeriesOutput {
    schema_version: u32,
    run_id: String,
    benchmark: SeriesInterval,
    window: SeriesWindow,
    filters: SeriesFilters,
    coverage: Vec<SeriesCoverage>,
    #[serde(flatten)]
    data: SeriesData,
}

#[derive(serde::Serialize)]
struct SeriesInterval {
    started_at: String,
    finished_at: String,
}

#[derive(serde::Serialize)]
struct SeriesWindow {
    name: String,
    started_at: String,
    finished_at: String,
    from_seconds: i64,
    to_seconds: i64,
    bucket_seconds: u64,
    /// 5秒bucketで集計した値（HTTP、DB、perf、client）の区間の端。`exact`は端がbucketの区切りか、
    /// node上で振り分けた境界（ベンチの始まりと終わり）に一致している。`approximate`は端をまたぐ
    /// bucketがあり、始まり側のbucketは含めず、終わり側のbucketは含めている。
    edges: &'static str,
}

#[derive(serde::Serialize)]
struct SeriesFilters {
    metrics: Vec<String>,
    node: Option<String>,
    labels: Vec<SeriesLabelFilter>,
}

#[derive(serde::Serialize)]
struct SeriesLabelFilter {
    key: String,
    value: String,
}

#[derive(serde::Serialize)]
struct SeriesCoverage {
    collector: String,
    node: String,
    phase: String,
    status: String,
    exit_code: Option<i32>,
    error: Option<String>,
}

#[derive(serde::Serialize)]
#[serde(tag = "mode", rename_all = "snake_case")]
enum SeriesData {
    Overview {
        total_count: usize,
        truncated: bool,
        rows: Vec<OverviewSeriesRow>,
    },
    Metrics {
        total_count: usize,
        truncated: bool,
        rows: Vec<MetricSeriesRow>,
    },
}

#[derive(serde::Serialize)]
struct OverviewSeriesRow {
    node: String,
    from_seconds: i64,
    to_seconds: i64,
    cpu_percent_average: Option<f64>,
    cpu_percent_max: Option<f64>,
    memory_used_mib_average: Option<f64>,
    load1_max: Option<f64>,
    disk_util_percent_max: Option<f64>,
    disk_await_ms_max: Option<f64>,
    http_requests: Option<f64>,
    http_p95_ms_max_of_quantile: Option<f64>,
    http_errors: Option<f64>,
    db_calls: Option<f64>,
    db_total_duration_ms: Option<f64>,
}

#[derive(serde::Serialize)]
struct MetricSeriesRow {
    node: String,
    from_seconds: i64,
    to_seconds: i64,
    metric: String,
    value: f64,
    unit: String,
    aggregation: MetricAggregation,
    labels: BTreeMap<String, String>,
}

fn parse_since(value: &str) -> std::result::Result<chrono::DateTime<chrono::Utc>, String> {
    if let Ok(at) = chrono::DateTime::parse_from_rfc3339(value) {
        return Ok(at.with_timezone(&chrono::Utc));
    benchmark_start: chrono::DateTime<chrono::Utc>,
    benchmark_end: chrono::DateTime<chrono::Utc>,
    window_start: chrono::DateTime<chrono::Utc>,
    window_end: chrono::DateTime<chrono::Utc>,
    options: &SeriesOptions,
    edges: &'static str,
    coverage: Vec<SeriesCoverage>,
    data: SeriesData,
) -> SeriesOutput {
    SeriesOutput {
        schema_version: 1,
        run_id,
        benchmark: SeriesInterval {
            started_at: benchmark_start.to_rfc3339(),
            finished_at: benchmark_end.to_rfc3339(),
        },
        window: SeriesWindow {
            name: options.window.as_str().into(),
            started_at: window_start.to_rfc3339(),
            finished_at: window_end.to_rfc3339(),
            from_seconds: (window_start - benchmark_start).num_seconds(),
            to_seconds: (window_end - benchmark_start).num_seconds(),
            bucket_seconds: options.bucket,
            edges,
        },
        filters: SeriesFilters {
            metrics: options.metrics.clone(),
            node: options.node.clone(),
            labels: options
                .labels
                .iter()
                .map(|(key, value)| SeriesLabelFilter {
                    key: key.clone(),
                    value: value.clone(),
                })
                .collect(),
        },
        coverage,
        data,
    }
}

/// 区間の端が5秒bucketで正確に切れているか（[`SeriesWindow::edges`]）。端がbucketの区切りか、
/// node上で行を振り分けた境界（ベンチの始まりと終わり）なら正確。bucketの区切りは保存された
