 for(const x of [x0,(x0+x1)/2,x1])svg.append(svgEl('text',{x:px(x),y:140,'text-anchor':'middle',class:'score-axis'},num(x-x0,1)+'s'));
 const legend=el('div',null,'chart-legend');card.append(legend);
