   d+=(previous==null||gap?'M':'L')+px(p.x)+' '+py(p.y)+' ';previous=p.x;
   const dot=svgEl('circle',{cx:px(p.x),cy:py(p.y),r:2.3,fill:color});dot.append(svgEl('title',{},`${s.name} · ${num(p.x-x0,1)}s · ${num(p.y,2)} ${unit}`));svg.append(dot);
  }
